2	몇 해 전부턴가, 찬바람 들기 시작할 때면 가까운 이들의 부모님 부고 소식. 그게 익숙해져가는 그런 나이. 그러하니 여전히 제 앞장만 가리고 살 때 당신께서 무탈한 것만으로도 감사한 일.\n\n올 동절기도 #배정숙쌍화차 를 개시하고, 밀영은 고창 검정밀의 남도흑밀케익을 #흑임자와단팥생크림케익 으로 새롭게.\n\n10.31(화)	[0.06731185,-0.00302003,-0.02169379,-0.04057783,0.07332607,-0.01759236,0.04139261,0.05649306,0.05547907,0.0640732,0.04441891,-0.00026336,0.08808751,-0.0206998,-0.01117192,0.03887941,0.0573551,-0.03534402,-0.05335744,-0.06065192,0.05873724,0.01108854,-0.06668292,0.064239,0.03490061,0.04559948,-0.00480561,0.03850638,0.08487869,-0.03615881,-0.04225408,-0.07313187,0.00315208,-0.05580379,0.0928102,0.03793116,-0.04639872,-0.06854974,0.05003369,-0.04611357,0.03215678,0.04358354,0.05707718,0.07648519,0.08931056,0.04001051,-0.03049223,0.10133412,-0.04619981,-0.06405571,-0.03134754,0.02009995,0.03017195,0.06274799,0.03873536,-0.01861454,-0.02221059,-0.02528052,-0.06641793,0.04127623,0.10267588,0.00975797,-0.0155906,-0.00327421,0.07835803,0.03879847,0.04989554,0.0470012,0.00132093,-0.01758923,-0.02622323,0.0556571,0.00135917,-0.05735881,0.02021673,0.0310035,0.08034587,-0.09003627,0.04509258,-0.01820308,-0.03254591,-0.04281526,-0.06738044,0.03150306,-0.02409604,0.08238479,0.01630391,-0.06296851,0.0695273,-0.02392154,0.04595914,0.07832381,-0.06228739,-0.0443308,-0.05111669,-0.02965062,-0.04882709,0.06337454,0.05042865,-0.03374504,0.05546081,-0.07685808,0.02131818,-0.04416953,-0.04949781,0.05590607,0.02144327,-0.03048058,0.0841028,-0.06636021,-0.04986978,0.00571012,0.02840229,0.04205388,-0.10633913,-0.01504779,0.0055447,-0.06668593,0.07085919,-0.08109216,0.07864519,-0.01286003,-0.07065777,-0.03354435,-0.04580894,-0.00811781,0.03093099,0.04072261,0.0437995,-0.00971204,0.06668262,0.01381926,0.01222705,0.04398336,0.05495378,0.07961857,-0.03247108,0.00195633,-0.04297983,-0.03896255,-0.00674899,0.0508533,-0.03952591,0.07454454,0.01718619,0.05560387,0.07556688,-0.02886515,0.12341733,-0.06483467,0.07887317,-0.01518908,0.04533357,0.05338048,0.01275173,-0.0760879,-0.02750266,-0.02284146,0.01759412,0.093216